        font-family: 'Oswald', sans-serif;
        font-size: 90px;
        font-weight: 700;
        color: #06b6d4;
        margin-bottom: 10px;
        text-shadow: 0 0 20px rgba(6,182,212,0.4);
    }

    .metric-box.primary .metric-value {
        font-size: 130px;
        color: #22d3ee;
    }

    .metric-label {
        font-size: 26px;
        font-weight: 600;
        color: #cbd5e1;
        text-transform: uppercase;
        letter-spacing: 1.5px;
    }

    .content-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        grid-gap: 60px;
        flex: 1;
        margin-top: 20px;
