        background: rgba(15, 23, 42, 0.5);
        border: 1px solid rgba(56, 189, 248, 0.15);
        border-radius: 20px;
        padding: 40px;
        display: flex;
        flex-direction: column;
        box-shadow: 0 10px 30px rgba(0,0,0,0.3);
    }

    .section.full-width {
        grid-column: 1 / -1;
    }

    .chart-container {
        flex: 1;
        min-height: 500px;
        position: relative;
    }

    .chart-container-large {
        flex: 1;
        min-height: 400px;
        position: relative;
    }

    .footer {
        text-align: center;
        margin-top: auto;
        padding-top: 40px;
        font-size: 20px;
        color: #64748b;
        border-top: 1px solid rgba(148, 163, 184, 0.1);
    }

    /* Extra specific styles for AntV SVG texts */
    svg {
        background: transparent !important;
    }
  </style>
</head>
<body>
  <div class="poster-container">
    <div class="header">
      <h1>Global Internet Usage</h1>
      <p>A data-driven comparison of internet penetration, digital population size, and online behavior across the world's leading digital economies.</p>
      <div class="main-metric">
        <div class="metric-box primary">
          <div class="metric-value">~5.56 Billion</div>
          <div class="metric-label">Global Internet Users (2025)</div>
        </div>
        <div class="metric-box">
          <div class="metric-value">~68%</div>
          <div class="metric-label">Global Penetration Rate</div>
        </div>
      </div>
