    <div class="content-grid">
      <!-- Top Countries -->
      <div class="section" style="grid-column: 1 / -1;">
        <div id="chart-population" class="chart-container-large"></div>
      </div>

      <!-- Penetration Rates -->
      <div class="section">
        <div id="chart-penetration" class="chart-container"></div>
      </div>

      <!-- Social Media & Economy -->
      <div class="section" style="display: flex; flex-direction: column; gap: 40px; background: transparent; border: none; padding: 0; box-shadow: none;">
        <div class="section" style="flex: 1;">
          <div id="chart-social" class="chart-container"></div>
        </div>
        <div class="section" style="flex: 1.2;">
          <div id="chart-economy" class="chart-container"></div>
        </div>
      </div>
    </div>

    <div class="footer">
      Source: 2025 Global Digital Economy Report | Produced via AntV Infographic
    </div>
  </div>

  <script src="/vendor/infographic.min.js"></script>
  <script>
    const data1 = `infographic chart-bar-plain-text
data
  title Top Countries by Online Population (Millions)
  desc China and India represent a massive share of the global digital population
  values
    - label China
      value 1090
    - label India
      value 900
    - label US
      value 320
    - label Indonesia
      value 220
    - label Brazil
      value 190
    - label Japan
      value 118
    - label Nigeria
      value 115
    - label Germany
      value 80
    - label UK
      value 66
    - label South Korea
      value 50
theme
  palette #06b6d4 #14b8a6 #3b82f6 #0ea5e9`;

    const data2 = `infographic chart-column-simple
data
  title Internet Penetration Rates by Country (%)
  desc Disparities persist between regions and countries
  values
    - label South Korea
      value 98
    - label UK
      value 97
    - label Germany
      value 96
    - label Japan
      value 95
    - label US
      value 95
    - label Brazil
      value 88
    - label Indonesia
      value 78
    - label China
      value 76
    - label India
      value 62
    - label Nigeria
      value 52
theme
  palette #14b8a6 #0ea5e9 #3b82f6`;

    const data3 = `infographic list-grid-badge-card
data
  title Top Social Platforms
  desc Daily usage reached ~143 mins in 2025
  lists
    - label Facebook
      desc ~3.1B
      icon facebook
    - label YouTube
      desc ~2.5B
      icon youtube
    - label WhatsApp
      desc ~2.4B
      icon whatsapp
    - label Instagram
      desc ~2.0B
      icon instagram
    - label TikTok
      desc ~1.6B
      icon tiktok
theme
  palette #3b82f6 #0ea5e9 #06b6d4`;

    const data4 = `infographic list-zigzag-down-compact-card
data
  title The Digital Economy Impact
  desc Connecting connectivity to real-world outcomes
  lists
    - label Mobile Dominance
      desc >60% of all web traffic worldwide
      icon smartphone
    - label Data Generation
      desc 180+ zettabytes created by 2025
      icon server
    - label AI Market
      desc Grow from $240B to >$800B by 2030
      icon star
    - label E-Commerce
      desc $8.0T projected retail sales by 2027
      icon shopping cart
theme
  palette #06b6d4 #14b8a6 #3b82f6 #0284c7`;

    function renderInfo(id, syntax) {
      try {
        const instance = new AntVInfographic.Infographic({
            container: '#' + id,
            width: '100%',
            height: '100%',
        });
        instance.render(syntax);
      } catch(e) {
        console.error("Error rendering " + id, e);
      }
    }

    renderInfo('chart-population', data1);
    renderInfo('chart-penetration', data2);
    renderInfo('chart-social', data3);
    renderInfo('chart-economy', data4);

    // After a short delay, fix text colors for dark theme
    setTimeout(() => {
        document.querySelectorAll('svg text').forEach(t => {
            const fill = t.getAttribute('fill') || getComputedStyle(t).fill;
            // if it's dark gray or black
            if (fill === '#262626' || fill === '#000000' || fill === 'rgb(38, 38, 38)' || fill === 'rgb(0, 0, 0)') {
                t.setAttribute('fill', '#e2e8f0');
                t.style.fill = '#e2e8f0';
            }
        });

        // Let playwright know we are ready
        window.INFOGRAPHIC_READY = true;
    }, 1000);
  </script>
</body>
</html>
